const CATS=["All","Residential","Commercial and Retail","Interior Design","Hospitality and Wellness","High-Rise and BIM"];
const fb=document.getElementById('filters'),pg=document.getElementById('pg'),dlg=document.getElementById('dlg');
function show(c){
 fb.innerHTML=CATS.map(x=>`<button class="${x===c?'on':''}" aria-pressed="${x===c}" data-c="${x}">${x}</button>`).join('');
 const l=P.filter(p=>c==='All'||p[1]===c);
 pg.innerHTML=l.length?l.map(p=>`<article class="card proj"><img class="${p[1]==='High-Rise and BIM'?'fit':''}" src="${IMG[p[2]][0]}" alt="${p[0]} architectural render or project photograph" loading="lazy"><div class="b"><span class="tag">${p[1]}</span><h3>${p[0]}</h3><button class="btn" data-p="${p[0]}">View Project</button></div></article>`).join(''):'<p class="note">Projects in this category will be added from the portfolio.</p>';
}
show('All');
fb.onclick=e=>{if(e.target.dataset.c)show(e.target.dataset.c)};
pg.onclick=e=>{const n=e.target.dataset.p;if(!n)return;const p=P.find(x=>x[0]===n);dname.textContent=p[0];dcat.textContent=p[1];dimg.innerHTML=IMG[p[2]].map(u=>`<img src="${u}" alt="${p[0]}">`).join('');dmeta.innerHTML=p[3]?Object.entries(p[3]).map(([k,v])=>`<p><b>${k}:</b> ${v}</p>`).join(''):'<p class="note">Images are from the MVM work portfolio. Location, scope and deliverables will appear here once added.</p>';dlg.showModal()};
dx.onclick=()=>dlg.close();dgo.onclick=()=>dlg.close();
const nav=document.getElementById('nav'),mb=document.getElementById('menu');
mb.onclick=()=>{const o=nav.classList.toggle('open');mb.setAttribute('aria-expanded',o)};
nav.onclick=e=>{if(e.target.tagName==='A')nav.classList.remove('open')};
document.addEventListener('click',e=>{const s=e.target.dataset&&e.target.dataset.svc;if(s)document.querySelector('[name=service]').value=SVC.find(x=>x[1]===s)?({"Architectural Design":"Architectural Design","BIM Management & Implementation":"BIM Management","BIM Information Management & Compliance":"ISO 19650 and Information Management","Project & Construction Management":"Project Coordination","BIM Outsourcing & Digital Delivery":"BIM Modeling"}[s]):''});
const secs=[...document.querySelectorAll('main section[id]')];
addEventListener('scroll',()=>{let c='home';secs.forEach(s=>{if(s.getBoundingClientRect().top<120)c=s.id});document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('on',a.getAttribute('href')==='#'+c))},{passive:true});
f.onsubmit=e=>{e.preventDefault();let ok=true;
 f.querySelectorAll('[required]').forEach(i=>{const m=i.closest('div').querySelector('.err');let msg='';
  if(!i.value.trim())msg='Required';else if(i.type==='email'&&!/^\S+@\S+\.\S+$/.test(i.value))msg='Enter a valid email';
  m.textContent=msg;if(msg)ok=false});
 if(!ok)return;
 const d=Object.fromEntries(new FormData(f));
 const body=Object.entries({Name:d.name,Email:d.email,Organization:d.company,Service:d.service,'Project type':d.ptype,Location:d.loc,Budget:d.budget,Timeline:d.timeline,Description:d.desc}).map(([k,v])=>k+': '+(v||'-')).join('\n');
 const mail=()=>{location.href='mailto:'+CFG.email+'?subject='+encodeURIComponent('Project inquiry: '+d.service)+'&body='+encodeURIComponent(body)};
 const done=m=>{const o=$('ok');o.textContent=m;o.style.display='block';f.reset()};
 if(CFG.formEndpoint){fetch(CFG.formEndpoint,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(d)}).then(r=>r.ok?done('Thank you! Your inquiry has been sent.'):Promise.reject()).catch(()=>{mail();done('We could not send automatically, so your email app should open instead.')})}
 else{mail();done('Thank you! Your email app should open with your inquiry ready to send. If not, email '+CFG.email+'.')}};
